upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
root=/var/lib/news-flow/qc-complete27-20261122
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gunzipSync,gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {declaredWordpressPostEndpoint} from './src/web/newsResearchTransport.mjs';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),root='/var/lib/news-flow/qc-complete27-20261122',p=JSON.parse(fs.readFileSync(root+'/residual-articles.json')).pages.find(p=>p.error==='NEWS_MISSING_DESCRIPTION'),html=gunzipSync(fs.readFileSync(p.file)).toString(),$=ch.load(html),api=declaredWordpressPostEndpoint(html,p.url,{allowDeclaredHost:true}),registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},pool,network,allowedDomains:registry.allowedDomains,profiles:JSON.parse(fs.readFileSync('config/web-sources/news-http-profiles.json')),siteCooldown:false,maxWireRequests:2}),out={at:new Date().toISOString(),url:p.url,api,nativeSapo:$('.td-post-sub-title,.sapo,[itemprop=description]').text(),metas:$('meta[name=description],meta[property="og:description"]').map((i,e)=>$(e).attr('content')).get()};try{if(api){const page=await driver.get('qc27-native-description',api,registry.sources.get(p.site).config,[],{reviewFailed:true,taskRole:'publisher_dependency'});out.error=page.error;out.statusCode=page.statusCode;if(!page.error&&page.html){out.file=root+'/evidence/'+createHash('sha256').update(page.html).digest('hex')+'.gz';fs.writeFileSync(out.file,gzipSync(page.html));const d=JSON.parse(page.html);out.post={id:d.id,link:d.link,title:d.title?.rendered,date_gmt:d.date_gmt,excerpt:d.excerpt?.rendered,bodyChars:d.content?.rendered?.length};}}fs.writeFileSync(root+'/native-description-check.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out));}finally{await network.close();}
